    let s1 = w2 + w3;
    let inv = vec3f(1.0) / dims;
    let h0 = inv * ((w1 / s0) - 0.5 + idx);
    let h1 = inv * ((w3 / s1) + 1.5 + idx);
    var c000 = textureSampleLevel(tex, samp, vec3f(h0.x, h0.y, h0.z), 0.0);
    let c100 = textureSampleLevel(tex, samp, vec3f(h1.x, h0.y, h0.z), 0.0);
